#define MAXN 50005
#define MAXE 100005

int head[MAXN], to[MAXE], nxt[MAXE], ecnt;

void addEdge(int u, int v) {
    to[++ecnt] = v;
    nxt[ecnt] = head[u];
    head[u] = ecnt;
}

int main() {
    int N;
    scanf("%d", &N);

    for (int i = 1; i <= N; ++i) head[i] = -1;
    ecnt = 0;

    for (int i = 0; i < N - 1; ++i) {
        int x, y;
        scanf("%d %d", &x, &y);
        addEdge(x, y);
        addEdge(y, x);
    }

    int parent[MAXN], order[MAXN];
    int top = 0;

    parent[1] = 0;
    order[top++] = 1;

    for (int i = 0; i < top; ++i) {
        int u = order[i];
        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (v == parent[u]) continue;
            parent[v] = u;
            order[top++] = v;
        }
    }

    long long height[MAXN], cnt[MAXN];
    long long best = 0, bestCnt = 0;

    for (int idx = N - 1; idx >= 0; --idx) {
        int u = order[idx];

        int prevMax = 0;
        long long prevMaxCount = 1;

        int localBest = -1;
        long long localCnt = 0;

        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (parent[v] != u) continue;

            int h = (int)height[v] + 1;
            long long c = cnt[v];

            int sum = h + prevMax;
            if (sum > localBest) {
                localBest = sum;
                localCnt = c * prevMaxCount;
            } else if (sum == localBest) {
                localCnt += c * prevMaxCount;
            }

            if (h > prevMax) {
                prevMax = h;
                prevMaxCount = c;
            } else if (h == prevMax) {
                prevMaxCount += c;
            }
        }

        height[u] = prevMax;
        cnt[u] = prevMaxCount;

        if (localBest >= 0) {
            if (localBest > best) {
                best = localBest;
                bestCnt = localCnt;
            } else if (localBest == best) {
                bestCnt += localCnt;
            }
        }
    }

    printf("%lld\n%lld\n", best + 1, bestCnt);

    return 0;
}
