#include <stdio.h>

#define MAXN 50005

int head[MAXN], to[2 * MAXN], nxt[2 * MAXN], ecnt;
int dist1[MAXN], dist2[MAXN], parent[MAXN];
int path[MAXN];
int stNode[MAXN], stPar[MAXN], stDep[MAXN];
int N;

void addEdge(int u, int v) {
    to[++ecnt] = v;
    nxt[ecnt] = head[u];
    head[u] = ecnt;
}

int bfs(int start, int *dist, int *par) {
    int q[MAXN];
    int front = 0, rear = 0;

    for (int i = 1; i <= N; i++) dist[i] = -1;

    dist[start] = 0;
    par[start] = 0;
    q[rear++] = start;

    int far = start;

    while (front < rear) {
        int u = q[front++];

        if (dist[u] > dist[far]) far = u;

        for (int e = head[u]; e; e = nxt[e]) {
            int v = to[e];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                par[v] = u;
                q[rear++] = v;
            }
        }
    }

    return far;
}

long long count_depth(int start, int parent, int startDepth, int target) {
    int top = 0;

    stNode[top] = start;
    stPar[top] = parent;
    stDep[top] = startDepth;
    top++;

    long long cnt = 0;

    while (top > 0) {
        --top;

        int u = stNode[top];
        int p = stPar[top];
        int d = stDep[top];

        if (d == target) {
            cnt++;
            continue;
        }

        if (d > target) continue;

        for (int e = head[u]; e; e = nxt[e]) {
            int v = to[e];
            if (v == p) continue;

            stNode[top] = v;
            stPar[top] = u;
            stDep[top] = d + 1;
            top++;
        }
    }

    return cnt;
}

int main() {
    scanf("%d", &N);

    ecnt = 0;
    for (int i = 1; i <= N; i++) head[i] = 0;

    for (int i = 0; i < N - 1; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        addEdge(x, y);
        addEdge(y, x);
    }

    int A = bfs(1, dist1, parent);
    int B = bfs(A, dist2, parent);

    int D = dist2[B];

    int cur = B;
    int len = 0;

    while (cur != 0) {
        path[len++] = cur;
        cur = parent[cur];
    }

    for (int i = 0; i < len / 2; i++) {
        int tmp = path[i];
        path[i] = path[len - 1 - i];
        path[len - 1 - i] = tmp;
    }

    long long ans;

    if (D % 2 == 0) {
        int r = D / 2;
        int c = path[r];

        ans = 0;
        long long total = 0;

        for (int e = head[c]; e; e = nxt[e]) {
            int nb = to[e];
            long long cnt = count_depth(nb, c, 1, r);
            ans += cnt * total;
            total += cnt;
        }
    } else {
        int r = D / 2;
        int c1 = path[r];
        int c2 = path[r + 1];

        long long cnt1 = count_depth(c1, c2, 0, r);
        long long cnt2 = count_depth(c2, c1, 0, r);

        ans = cnt1 * cnt2;
    }

    printf("%d\n%lld\n", D + 1, ans);

    return 0;
}
